begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values
 ('10000000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Bounded marking fixture','Synthetic','PUBLISHED'),
 ('10000000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000005','Other owner source','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id)select'10000000-0000-4000-8000-000000000001',('99010000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,case when i=102 then'99000000-0000-4000-8000-000000000002'::uuid else'99000000-0000-4000-8000-000000000001'::uuid end,case when i=102 then'20000000-0000-4000-8000-000000000005'::uuid else'20000000-0000-4000-8000-000000000004'::uuid end,'Bounded task '||i,'School authored',10,'61000000-0000-4000-8000-000000000001'from generate_series(1,102)i;
insert into app.submissions(school_id,id,assessment_id,learner_id,content)select'10000000-0000-4000-8000-000000000001',('99020000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,('99010000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'20000000-0000-4000-8000-000000000012','Immutable bounded source'from generate_series(1,102)i;
set local role cuevo_api;set local statement_timeout='5s';select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select lives_ok($$select internal.read_current_marking_page(100,'99000000-0000-4000-8000-000000000000')$$,'101 current source fixture reads within unchanged five second database budget');
select is(jsonb_array_length(internal.read_current_marking_page(100,'99000000-0000-4000-8000-000000000000')->'items'),100,'native details materialize only the requested100 source rows');
select ok(internal.read_current_marking_page(100,'99000000-0000-4000-8000-000000000000')->>'nextCursor'is not null,'101 source fixture retains cursor sentinel');
select is((select count(*)from jsonb_array_elements(internal.read_current_marking_page(100,(internal.read_current_marking_page(100,'99000000-0000-4000-8000-000000000000')->>'nextCursor')::uuid)->'items')item where item->>'assessmentId'like'99010000-%'),1::bigint,'following page has exact one remaining authorized fixture source');
select ok(not exists(select 1 from jsonb_array_elements(internal.read_current_marking_page(100,'99000000-0000-4000-8000-000000000000')->'items')item where item->>'assessmentId'='99010000-0000-4000-8000-000000000102'),'teacher cannot read another owner source despite same class');
select internal.return_learning_submission('99020000-0000-4000-8000-000000000001','Teacher return source feedback',1);
select internal.close_learning_submission('99020000-0000-4000-8000-000000000002',1);
select ok(exists(select 1 from jsonb_array_elements(internal.read_current_marking_page(100,'99000000-0000-4000-8000-000000000000')->'items')item where item->>'id'='99020000-0000-4000-8000-000000000001'and item->>'submissionStatus'='RETURNED'),'returned current source stays visible with explicit non-open lifecycle');
select ok(exists(select 1 from jsonb_array_elements(internal.read_current_marking_page(100,'99000000-0000-4000-8000-000000000000')->'items')item where item->>'id'='99020000-0000-4000-8000-000000000002'and item->>'submissionStatus'='CLOSED'),'closed current source stays visible without new mark authority');
select is("authorization".current_submission_open('10000000-0000-4000-8000-000000000001','99020000-0000-4000-8000-000000000001'),false,'bounded read does not reopen returned source');
select is("authorization".current_submission_open('10000000-0000-4000-8000-000000000001','99020000-0000-4000-8000-000000000002'),false,'bounded read does not reopen closed source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select ok(exists(select 1 from jsonb_array_elements(internal.read_current_marking_page(100,'99020000-0000-4000-8000-000000000101')->'items')item where item->>'assessmentId'='99010000-0000-4000-8000-000000000102'),'current administrator can read another teacher-owned source within the authorized class');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
reset role;savepoint marking_enrollment_revoked;
update app.enrollments set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and class_id='30000000-0000-4000-8000-000000000001'and student_actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;
select is((select count(*)from jsonb_array_elements(internal.read_current_marking_page(100,'99000000-0000-4000-8000-000000000000')->'items')item where item->>'assessmentId'like'99010000-%'),0::bigint,'current exact class enrollment revocation hides fixture raw marking source');
reset role;rollback to marking_enrollment_revoked;savepoint marking_teacher_revoked;
update app.teacher_assignments set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and teacher_actor_id='20000000-0000-4000-8000-000000000004';
set local role cuevo_api;
select is(jsonb_array_length(internal.read_current_marking_page(100,null)->'items'),0,'teacher current assignment revocation hides marking sources');
reset role;rollback to marking_teacher_revoked;
set local role cuevo_api;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select throws_ok('select internal.read_current_marking_page(25,null)','42501',null,'student cannot read private raw marking page');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select throws_ok('select internal.read_current_marking_page(25,null)','42501',null,'parent cannot read private raw marking page');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select throws_ok('select internal.read_current_marking_page(101,null)','22023',null,'unbounded native detail page denied');
select set_config('app.school_id','10000000-0000-4000-8000-000000000002',true);
select throws_ok('select internal.read_current_marking_page(25,null)','42501',null,'foreign tenant selector cannot authorize marking source');
reset role;
select ok(not has_function_privilege('authenticated','internal.read_current_marking_page(integer,uuid)','EXECUTE')and not has_function_privilege('cuevo_worker','internal.read_current_marking_page(integer,uuid)','EXECUTE'),'bounded marking source has no browser or worker grant');
select*from finish();rollback;
